export * as Menu from './menu.tsx';
export type {
  CheckboxItemOwnProps as MenuCheckboxItemOwnProps,
  CheckboxItemProps as MenuCheckboxItemProps,
  ContentOwnProps as MenuContentOwnProps,
  ContentProps as MenuContentProps,
  ItemOwnProps as MenuItemOwnProps,
  ItemProps as MenuItemProps,
  RadioItemOwnProps as MenuRadioItemOwnProps,
  RadioItemProps as MenuRadioItemProps,
  SubmenuTriggerOwnProps as MenuSubmenuTriggerOwnProps,
  SubmenuTriggerProps as MenuSubmenuTriggerProps,
} from './menu.tsx';

@layer hj.components {
  /* Customise: --hj-menu-width · --hj-menu-item-height · --hj-menu-radius */
  .hj-menu-positioner {
    z-index: var(--hj-z-popover);
    outline: none;
  }
  .hj-menu-backdrop {
    position: fixed;
    inset: 0;
  }

  .hj-menu-popup {
    min-width: var(--hj-menu-width, 208px);
    max-width: min(320px, var(--available-width, 100vw));
    max-height: var(--available-height, 70vh);
    overflow-y: auto;
    padding: calc(5px * var(--hj-density));
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-menu-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    /* Grows from the button that made it. */
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-menu-popup[data-starting-style],
  .hj-menu-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.92);
  }
  .hj-menu-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-menu-popup[data-instant] {
    transition: none;
  }

  .hj-menu-item {
    position: relative;
    display: flex;
    align-items: center;
    gap: calc(10px * var(--hj-density));
    min-height: var(--hj-menu-item-height, calc(36px * var(--hj-density-size)));
    padding: 0 calc(10px * var(--hj-density));
    border-radius: var(--hj-radius-xs);
    corner-shape: var(--hj-corner-shape, round);
    font-size: 14px;
    font-weight: 500;
    line-height: 1.25;
    color: var(--hj-fg);
    text-decoration: none;
    cursor: default;
    outline: none;
    user-select: none;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-menu-item[data-highlighted] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
  }
  .hj-menu-item[data-popup-open] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
  }
  .hj-menu-item[data-disabled] {
    color: var(--hj-fg-mute);
    opacity: 0.4;
  }
  .hj-menu-item > .hj-icon {
    font-size: 18px;
    color: var(--hj-fg-dim);
  }
  .hj-menu-item[data-tone='danger'],
  .hj-menu-item[data-tone='danger'] > .hj-icon {
    color: var(--hj-danger-text);
  }
  .hj-menu-item[data-tone='danger'][data-highlighted] {
    background: var(--hj-danger-soft);
  }

  .hj-menu-shortcut {
    margin-left: auto;
    padding-left: calc(16px * var(--hj-density));
    font: 500 11.5px / 1 var(--hj-font-mono);
    letter-spacing: 0.02em;
    color: var(--hj-fg-mute);
  }
  .hj-menu-chevron {
    display: inline-flex;
    margin-left: auto;
    margin-right: calc(-4px * var(--hj-density));
    font-size: 16px;
    line-height: 0;
    color: var(--hj-fg-mute);
  }
  .hj-menu-chevron > svg {
    width: 16px;
    height: 16px;
  }

  /* Check and dot: a fixed column so labels align; the mark scales in on a settled spring. */
  .hj-menu-indicator {
    display: inline-grid;
    flex: none;
    place-items: center;
    width: 16px;
    height: 16px;
    margin-left: -2px;
    color: var(--hj-accent-text);
    line-height: 0;
  }
  .hj-menu-indicator > svg {
    width: 15px;
    height: 15px;
    stroke-width: 2;
    transform: scale(0.4);
    opacity: 0;
    transition:
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle),
      opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-menu-indicator[data-checked] > svg {
    transform: none;
    opacity: 1;
  }
  .hj-menu-dot {
    width: 7px;
    height: 7px;
    border-radius: var(--hj-radius-pill);
    background: currentColor;
    transform: scale(0);
    transition: transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-menu-indicator[data-checked] > .hj-menu-dot {
    transform: none;
  }

  .hj-menu-group-label {
    padding: calc(10px * var(--hj-density)) calc(10px * var(--hj-density))
      calc(4px * var(--hj-density));
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
    cursor: default;
  }
  .hj-menu-separator {
    height: 1px;
    margin: calc(5px * var(--hj-density)) calc(-5px * var(--hj-density));
    border: 0;
    background: var(--hj-line);
  }

  .hj-menu-arrow {
    position: relative;
    display: block;
    width: 14px;
    height: 7px;
    overflow: clip;
  }
  .hj-menu-arrow[data-side='top'] {
    bottom: -7px;
    rotate: 180deg;
  }
  .hj-menu-arrow[data-side='bottom'] {
    top: -7px;
  }
  .hj-menu-arrow[data-side='left'] {
    right: -10px;
    rotate: 90deg;
  }
  .hj-menu-arrow[data-side='right'] {
    left: -10px;
    rotate: -90deg;
  }
  .hj-menu-arrow::before {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 10px;
    height: 10px;
    border: 1px solid var(--hj-line);
    background: var(--hj-surface-2);
    transform: translate(-50%, 50%) rotate(45deg);
  }
}

'use client';
import { Menu as Base } from '@base-ui/react/menu';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: typeof Base.Root = Base.Root;
export const SubmenuRoot: typeof Base.SubmenuRoot = Base.SubmenuRoot;
export const RadioGroup: typeof Base.RadioGroup = Base.RadioGroup;
export const createHandle: typeof Base.createHandle = Base.createHandle;

export const Trigger: HanjiPart<typeof Base.Trigger> = part(
  Base.Trigger,
  'Menu.Trigger',
  'hj-menu-trigger',
);
export const Positioner: HanjiPart<typeof Base.Positioner> = part(
  Base.Positioner,
  'Menu.Positioner',
  'hj-menu-positioner',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(Base.Popup, 'Menu.Popup', 'hj-menu-popup');
export const Arrow: HanjiPart<typeof Base.Arrow> = part(Base.Arrow, 'Menu.Arrow', 'hj-menu-arrow');
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Menu.Backdrop',
  'hj-menu-backdrop',
);
export const Group: HanjiPart<typeof Base.Group> = part(Base.Group, 'Menu.Group', 'hj-menu-group');
export const GroupLabel: HanjiPart<typeof Base.GroupLabel> = part(
  Base.GroupLabel,
  'Menu.GroupLabel',
  'hj-menu-group-label',
);
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'Menu.Separator',
  'hj-menu-separator',
);
export const LinkItem: HanjiPart<typeof Base.LinkItem> = part(
  Base.LinkItem,
  'Menu.LinkItem',
  'hj-menu-item',
);
/** A keyboard shortcut at the end of an item, set in mono. */
export const Shortcut: (props: ElementPartProps<'kbd'>) => React.ReactElement = elementPart(
  'kbd',
  'Menu.Shortcut',
  'hj-menu-shortcut',
);

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface ItemOwnProps {
  /** danger = a destructive verb: danger ink, a danger-tint highlight. Put it last. */
  tone?: 'default' | 'danger';
}
export interface ItemProps extends ItemOwnProps, Base.Item.Props {}

/** One command. Children: an optional `<Icon>`, the label, an optional `<Menu.Shortcut>`. */
export function Item(props: ItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const { tone = 'default', className, ...rest } = withDefaults(config, 'Menu.Item', props);
  return (
    <Base.Item
      {...rest}
      data-tone={tone === 'default' ? undefined : tone}
      className={cls(config, 'Menu.Item', 'hj-menu-item', className)}
    />
  );
}

export interface CheckboxItemOwnProps {
  /** Draw the check column. Turn off if you render your own CheckboxItemIndicator. @default true */
  indicator?: boolean;
}
export interface CheckboxItemProps extends CheckboxItemOwnProps, Base.CheckboxItem.Props {}

/** A toggled option. The check scales in on a settled spring; the menu stays open. */
export function CheckboxItem(props: CheckboxItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    indicator = true,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Menu.CheckboxItem', props);
  return (
    <Base.CheckboxItem
      {...rest}
      className={cls(config, 'Menu.CheckboxItem', 'hj-menu-item', className)}
    >
      {indicator ? (
        <Base.CheckboxItemIndicator
          keepMounted
          className={config.unstyled ? undefined : 'hj-menu-indicator'}
        >
          {config.icons.check}
        </Base.CheckboxItemIndicator>
      ) : null}
      {children}
    </Base.CheckboxItem>
  );
}

export interface RadioItemOwnProps {
  /** Draw the dot column. @default true */
  indicator?: boolean;
}
export interface RadioItemProps extends RadioItemOwnProps, Base.RadioItem.Props {}

/** One choice inside a Menu.RadioGroup. */
export function RadioItem(props: RadioItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    indicator = true,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Menu.RadioItem', props);
  const styled = !config.unstyled;
  return (
    <Base.RadioItem {...rest} className={cls(config, 'Menu.RadioItem', 'hj-menu-item', className)}>
      {indicator ? (
        <Base.RadioItemIndicator keepMounted className={styled ? 'hj-menu-indicator' : undefined}>
          <span className={styled ? 'hj-menu-dot' : undefined} />
        </Base.RadioItemIndicator>
      ) : null}
      {children}
    </Base.RadioItem>
  );
}

export const CheckboxItemIndicator: HanjiPart<typeof Base.CheckboxItemIndicator> = part(
  Base.CheckboxItemIndicator,
  'Menu.CheckboxItemIndicator',
  'hj-menu-indicator',
);
export const RadioItemIndicator: HanjiPart<typeof Base.RadioItemIndicator> = part(
  Base.RadioItemIndicator,
  'Menu.RadioItemIndicator',
  'hj-menu-indicator',
);

export interface SubmenuTriggerOwnProps {
  /** Draw the trailing chevron. @default true */
  chevron?: boolean;
}
export interface SubmenuTriggerProps extends SubmenuTriggerOwnProps, Base.SubmenuTrigger.Props {}

/** Opens a nested menu on hover, click or →. */
export function SubmenuTrigger(props: SubmenuTriggerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    chevron = true,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Menu.SubmenuTrigger', props);
  return (
    <Base.SubmenuTrigger
      {...rest}
      data-submenu=""
      className={cls(config, 'Menu.SubmenuTrigger', 'hj-menu-item', className)}
    >
      {children}
      {chevron ? (
        <span className={config.unstyled ? undefined : 'hj-menu-chevron'} aria-hidden="true">
          {config.icons.chevronRight}
        </span>
      ) : null}
    </Base.SubmenuTrigger>
  );
}

export interface ContentOwnProps {
  side?: Base.Positioner.Props['side'];
  align?: Base.Positioner.Props['align'];
  /** Gap from the trigger in px. @default 6 (hanji menu gap) */
  sideOffset?: Base.Positioner.Props['sideOffset'];
  alignOffset?: Base.Positioner.Props['alignOffset'];
  /** Keep this far from the viewport edge in px. @default 8 (hanji menu margin) */
  collisionPadding?: Base.Positioner.Props['collisionPadding'];
  container?: Base.Portal.Props['container'];
  keepMounted?: boolean;
}
export interface ContentProps extends ContentOwnProps, Base.Popup.Props {}

/** Shorthand for Portal + Positioner + Popup. Works for submenus too. */
export function Content(props: ContentProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    side,
    align,
    sideOffset = 6,
    alignOffset,
    collisionPadding = 8,
    container,
    keepMounted,
    ...popup
  } = withDefaults(config, 'Menu.Content', props);
  return (
    <Portal container={container} keepMounted={keepMounted}>
      <Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        collisionPadding={collisionPadding}
      >
        <Popup {...popup} />
      </Positioner>
    </Portal>
  );
}
